package ru.alfabank.api.accounts.util;

import org.apache.commons.lang3.StringUtils;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Component;
import ru.alfabank.api.accounts.configuration.AccountEntryNumberExtractorConfiguration;
import ru.alfabank.ws.cs.eq.wsaccountmovementlistinoutparms16.WSAccountMovementListGetOutResultSetRow;

import java.util.Collection;
import java.util.HashSet;

@Component
public class AccountEntryNumberExtractor {
    private final Collection<String> codesWithSpecialNumber;

    @Autowired
    public AccountEntryNumberExtractor(AccountEntryNumberExtractorConfiguration config) {
        this.codesWithSpecialNumber = new HashSet<>(config.getCodesWithSpecialNumber());
    }

    // Документы типа "09:Мемор. ордер" и "17:Банк. ордер" особенные и их номер может содержаться как в 201 так и в 110 полях сервиса.
    public String extract(WSAccountMovementListGetOutResultSetRow from) {
        if (StringUtils.isEmpty(from.getR201()) && codesWithSpecialNumber.contains(from.getR100())) {
            return from.getR110();
        } else {
            return from.getR201();
        }
    }
}
