package ru.alfabank.api.accounts.util;

import org.apache.commons.lang3.StringUtils;

import java.util.ArrayList;
import java.util.List;

import static java.lang.String.format;

/**
 * Created by aashatunov on 27/02/17.
 */
public class QueryBuilder {

    private StringBuilder query = new StringBuilder();

    public String toSql() {
        return query.toString();
    }

    public QueryBuilder or() {
        query.append(" OR ");
        return this;
    }

    public QueryBuilder and() {
        query.append(" AND ");
        return this;
    }

    public QueryBuilder withActIn(String... acts) {
        if (acts != null && acts.length > 0) {
            List<String> actList = new ArrayList<>(acts.length);
            for (String act : acts) {
                actList.add(StringUtils.wrap(act, '\''));
            }
            query.append(format("SCACT IN (%s)", StringUtils.join(actList, ',')));
        }
        return this;
    }

    public QueryBuilder withEanStartsWith(String... eans) {
        if (eans != null && eans.length > 0) {
            StringBuilder queryBuilder = new StringBuilder();
            for (String ean : eans) {
                if (queryBuilder.length() > 0) {
                    queryBuilder.append(" OR ");
                }
                queryBuilder.append("NEEAN LIKE '");
                queryBuilder.append(ean);
                queryBuilder.append("%'");
            }
            query.append(queryBuilder);
        }
        return this;
    }

    public QueryBuilder withSql(String sql) {
        if (StringUtils.isNotEmpty(sql)) {
            query.append(sql);
        }
        return this;
    }

}
